    33
    34
    35  static void
    36  test_face (hb_face_t *face,
    37             hb_codepoint_t cp)
    38  {
    39    hb_font_t *font = hb_font_create (face);
    40    hb_set_t *set;
    41    hb_codepoint_t g;
    42    hb_position_t x, y;
    43    char buf[5] = {0};
    44    unsigned int len;
    45    hb_glyph_extents_t extents;
    46    hb_ot_font_set_funcs (font);
    47
    48    set = hb_set_create ();
    49    hb_face_collect_unicodes (face, set);
    50    hb_face_collect_variation_selectors (face, set);
    51    hb_face_collect_variation_unicodes (face, cp, set);
    52
    53    hb_font_get_nominal_glyph (font, cp, &g);
    54    hb_font_get_variation_glyph (font, cp, cp, &g);
    55    hb_font_get_glyph_h_advance (font, cp);
    56    hb_font_get_glyph_v_advance (font, cp);
    57    hb_font_get_glyph_h_origin (font, cp, &x, &y);
    58    hb_font_get_glyph_v_origin (font, cp, &x, &y);
    59    hb_font_get_glyph_extents (font, cp, &extents);
    60    hb_font_get_glyph_contour_point (font, cp, 0, &x, &y);
    61    hb_font_get_glyph_name (font, cp, buf, sizeof (buf));
    62    hb_font_get_glyph_from_name (font, buf, strlen (buf), &g);
    63
    64    hb_ot_color_has_palettes (face);
    65    hb_ot_color_palette_get_count (face);
    66    hb_ot_color_palette_get_name_id (face, cp);
    67    hb_ot_color_palette_color_get_name_id (face, cp);
    68    hb_ot_color_palette_get_flags (face, cp);
    69    hb_ot_color_palette_get_colors (face, cp, 0, NULL, NULL);
    70    hb_ot_color_has_layers (face);
    71    hb_ot_color_glyph_get_layers (face, cp, 0, NULL, NULL);
    72    hb_ot_color_has_svg (face);
    73    hb_blob_destroy (hb_ot_color_glyph_reference_svg (face, cp));
    74    hb_ot_color_has_png (face);
    75    hb_blob_destroy (hb_ot_color_glyph_reference_png (font, cp));
    76
    77    hb_ot_layout_has_glyph_classes (face);
    78    hb_ot_layout_has_substitution (face);
    79    hb_ot_layout_has_positioning (face);
    80
    81    hb_ot_math_has_data (face);
    82    hb_ot_math_get_constant (font, HB_OT_MATH_CONSTANT_MATH_LEADING);
    83    hb_ot_math_get_glyph_italics_correction (font, cp);
    84    hb_ot_math_get_glyph_top_accent_attachment (font, cp);
    85    hb_ot_math_is_glyph_extended_shape (face, cp);
    86    hb_ot_math_get_glyph_kerning (font, cp, HB_OT_MATH_KERN_BOTTOM_RIGHT, 0);
    87    hb_ot_math_get_glyph_variants (font, cp, HB_DIRECTION_TTB, 0, NULL, NULL);
    88    hb_ot_math_get_min_connector_overlap (font, HB_DIRECTION_RTL);
    89    hb_ot_math_get_glyph_assembly (font, cp, HB_DIRECTION_BTT, 0, NULL, NULL, NULL);
    90
    91    len = sizeof (buf);
    92    hb_ot_name_list_names (face, NULL);
    93    hb_ot_name_get_utf8 (face, cp, NULL, &len, buf);
    94    hb_ot_name_get_utf16 (face, cp, NULL, NULL, NULL);
    95    hb_ot_name_get_utf32 (face, cp, NULL, NULL, NULL);
    96
    97    hb_ot_var_get_axis_count (face);
    98    hb_ot_var_get_axis_infos (face, 0, NULL, NULL);
    99    hb_ot_var_normalize_variations (face, NULL, 0, NULL, 0);
   100    hb_ot_var_normalize_coords (face, 0, NULL, NULL);
   101
   102    hb_set_destroy (set);
   103    hb_font_destroy (font);
   104  }
   105
   106  #ifndef TEST_OT_FACE_NO_MAIN
   107  static void
   108  test_ot_face_empty (void)
   109  {
   110    test_face (hb_face_get_empty (), 0);
   111  }
   112
   113  int
   114  main (int argc, char **argv)
   115  {
   116    hb_test_init (&argc, &argv);
   117
   118    hb_test_add (test_ot_face_empty);
   119
   120    return hb_test_run();
   121  }
   122  #endif
